def minimum_students_to_leave(heights):
    # Helper function to compute LIS length ending at each index
    def compute_lis(arr):
        n = len(arr)
        tails = []
        lis = [0] * n
        for i in range(n):
            v = arr[i]
            low, high = 0, len(tails)
            while low < high:
                mid = (low + high) // 2
                if tails[mid] >= v:
                    high = mid
                else:
                    low = mid + 1
            if low == len(tails):
                tails.append(v)
            else:
                tails[low] = v
            lis[i] = low + 1
        return lis

    n = len(heights)
    if n == 0:
        return 0
    # LIS ending at each position
    lis = compute_lis(heights)
    # LIS on reversed array corresponds to decreasing subsequence starting at each position
    rev_lis = compute_lis(heights[::-1])
    lds = [0] * n
    for i in range(n):
        lds[i] = rev_lis[n - 1 - i]
    # Find maximum bitonic length
    max_len = 0
    for i in range(n):
        curr = lis[i] + lds[i] - 1
        if curr > max_len:
            max_len = curr
    # Minimum students to remove
    return n - max_len

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.
    """
    n = len(heights)
    if n == 0:
        return 0

    # Longest increasing subsequence ending at each position
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # Longest decreasing subsequence starting at each position
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # Maximum length of a bitonic subsequence
    max_len = 0
    for i in range(n):
        bitonic_len = inc[i] + dec[i] - 1
        if bitonic_len > max_len:
            max_len = bitonic_len

    # Minimum students to leave
    return n - max_len

